        "groupType": "editable",
        "items": [
          {
            "type": 1,
            "content": { "json": "## Executive Summary \u2014 Security \u2194 ITSM Integration KPIs" },
            "name": "exec-title"
          },
          {
            "type": 3,
            "content": {
              "version": "KqlItem/1.0",
              "query": "union isfuzzy=true (datatable(TimeGenerated:datetime,RFC_NUMBER:string,TITLE:string,SEVERITY_ID:int,STATUS_EN:string,REQUESTOR_NAME:string,REQUESTOR_EMAIL:string,RECIPIENT_NAME:string,DEPARTMENT_PATH:string,LOCATION_PATH:string,ASSET_TAG:string,MAX_RESOLUTION_DATE_UT:datetime,REQUEST_TYPE:string,SUBMIT_DATE_UT:datetime,END_DATE_UT:datetime,LAST_UPDATE:datetime,DESCRIPTION:string,ORIGIN:string)[] | where 1==0), EasyVista_Tickets_CL\n| where TimeGenerated {TimeRange}\n| where REQUEST_TYPE has_any (\"Incident\", \"I\")\n| summarize\n    TotalTickets = count(),\n    OpenTickets = countif(STATUS_EN !in (\"Closed\", \"Resolved\")),\n    HighSeverity = countif(SEVERITY_ID <= 2),\n    AvgResolutionHours = round(avg(iff(isnotempty(END_DATE_UT), datetime_diff('hour', END_DATE_UT, SUBMIT_DATE_UT), real(null))), 1),\n    SLABreached = countif(isnotempty(MAX_RESOLUTION_DATE_UT) and MAX_RESOLUTION_DATE_UT < iif(isnotempty(END_DATE_UT), END_DATE_UT, now()))",
              "size": 4,
              "title": "Key Metrics",
              "queryType": 0,
              "visualization": "tiles",
              "tileSettings": {
                "titleContent": { "columnMatch": "Column1", "formatter": 1 },
                "leftContent": { "columnMatch": "TotalTickets", "formatter": 12, "numberFormat": { "unit": 17, "options": { "style": "decimal" } } },
                "showBorder": true
              }
            },
            "name": "exec-tiles"
          },
          {
            "type": 3,
            "content": {
              "version": "KqlItem/1.0",
              "query": "union isfuzzy=true (datatable(TimeGenerated:datetime,RFC_NUMBER:string,TITLE:string,SEVERITY_ID:int,STATUS_EN:string,REQUESTOR_NAME:string,REQUESTOR_EMAIL:string,RECIPIENT_NAME:string,DEPARTMENT_PATH:string,LOCATION_PATH:string,ASSET_TAG:string,MAX_RESOLUTION_DATE_UT:datetime,REQUEST_TYPE:string,SUBMIT_DATE_UT:datetime,END_DATE_UT:datetime,LAST_UPDATE:datetime,DESCRIPTION:string,ORIGIN:string)[] | where 1==0), EasyVista_Tickets_CL\n| where TimeGenerated {TimeRange}\n| where REQUEST_TYPE has_any (\"Incident\", \"I\")\n| summarize TicketCount = count() by bin(TimeGenerated, 1d), STATUS_EN\n| render timechart",
              "size": 0,
              "title": "Security Ticket Volume Trend (Daily)",
              "queryType": 0,
              "visualization": "timechart"
            },
            "name": "exec-trend"
          },
          {
            "type": 3,
            "content": {
              "version": "KqlItem/1.0",
              "query": "union isfuzzy=true (datatable(TimeGenerated:datetime,RFC_NUMBER:string,TITLE:string,SEVERITY_ID:int,STATUS_EN:string,REQUESTOR_NAME:string,REQUESTOR_EMAIL:string,RECIPIENT_NAME:string,DEPARTMENT_PATH:string,LOCATION_PATH:string,ASSET_TAG:string,MAX_RESOLUTION_DATE_UT:datetime,REQUEST_TYPE:string,SUBMIT_DATE_UT:datetime,END_DATE_UT:datetime,LAST_UPDATE:datetime,DESCRIPTION:string,ORIGIN:string)[] | where 1==0), EasyVista_Tickets_CL\n| where TimeGenerated {TimeRange}\n| where REQUEST_TYPE has_any (\"Incident\", \"I\")\n| summarize Tickets = count() by SEVERITY_ID\n| extend Severity = case(SEVERITY_ID == 1, \"Critical\", SEVERITY_ID == 2, \"High\", SEVERITY_ID == 3, \"Medium\", \"Low\")\n| project Severity, Tickets\n| render piechart",
              "size": 2,
              "title": "Incidents by Severity",
              "queryType": 0,
              "visualization": "piechart"
            },
            "customWidth": "50",
            "name": "exec-severity-pie"
          },
          {
            "type": 3,
            "content": {
              "version": "KqlItem/1.0",
              "query": "union isfuzzy=true (datatable(TimeGenerated:datetime,RFC_NUMBER:string,TITLE:string,SEVERITY_ID:int,STATUS_EN:string,REQUESTOR_NAME:string,REQUESTOR_EMAIL:string,RECIPIENT_NAME:string,DEPARTMENT_PATH:string,LOCATION_PATH:string,ASSET_TAG:string,MAX_RESOLUTION_DATE_UT:datetime,REQUEST_TYPE:string,SUBMIT_DATE_UT:datetime,END_DATE_UT:datetime,LAST_UPDATE:datetime,DESCRIPTION:string,ORIGIN:string)[] | where 1==0), EasyVista_Tickets_CL\n| where TimeGenerated {TimeRange}\n| where REQUEST_TYPE has_any (\"Incident\", \"I\")\n| summarize Tickets = count() by DEPARTMENT_PATH\n| top 10 by Tickets\n| render barchart",
              "size": 2,
