              "queryType": 0,
              "visualization": "barchart"
            },
            "customWidth": "50",
            "name": "exec-dept-bar"
          },
          {
            "type": 3,
            "content": {
              "version": "KqlItem/1.0",
              "query": "SecurityIncident\n| where TimeGenerated {TimeRange}\n| where Labels has \"EV:\"\n| extend EVTicket = extract(@\"EV:([^,\\]]+)\", 1, tostring(Labels))\n| summarize\n    SentinelIncidents = dcount(IncidentNumber),\n    LinkedToEV = dcountif(IncidentNumber, isnotempty(EVTicket)),\n    UnlinkedIncidents = dcountif(IncidentNumber, isempty(EVTicket))\n| extend LinkageRate = round(100.0 * LinkedToEV / SentinelIncidents, 1)",
              "size": 4,
              "title": "Sentinel \u2194 EasyVista Linkage Rate",
              "queryType": 0,
              "visualization": "tiles"
            },
            "name": "exec-linkage"
          },
          {
            "type": 3,
            "content": {
              "version": "KqlItem/1.0",
